package com.myassist.customer.ui;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.location.Location;import android.location.LocationListener;import android.location.LocationManager;import androidx.core.app.ActivityCompat;import android.os.Bundle;
public final class LocationHelper {public interface Callback{void onLocation(double lat,double lng);}private final Activity activity;private final LocationManager manager;public LocationHelper(Activity a){activity=a;manager=(LocationManager)a.getSystemService(Activity.LOCATION_SERVICE);}public void request(Callback cb){if(ActivityCompat.checkSelfPermission(activity,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(activity,new String[]{Manifest.permission.ACCESS_FINE_LOCATION},1001);return;}Location last=manager.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(last==null)last=manager.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);if(last!=null){cb.onLocation(last.getLatitude(),last.getLongitude());return;}manager.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,1000,1,new LocationListener(){public void onLocationChanged(Location l){cb.onLocation(l.getLatitude(),l.getLongitude());manager.removeUpdates(this);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}});}}
